{"path":"derived/tar-4f4f72add5183072/CTFd/templates/admin/statistics.html","source":{"source_path":"throwback_templates.tar.gz","source_sha256":"4f4f72add518307272c2e548587645f6f8be07f93b795637d34114acea29ab59","member_path":"CTFd/templates/admin/statistics.html"},"encoding":"utf-8","content":"{% extends "admin/base.html" %}

{% block content %}

<div class="row">
    <h1>Statistics</h1>

    <h3><b>{{ team_count }}</b> teams registered</h3>
    <h3><b>{{ wrong_count }}</b> wrong keys submitted</h3>
    <h3><b>{{ solve_count }}</b> right keys submitted</h3>
    <h3><b>{{ challenge_count }}</b> challenges</h3>
    {% if most_solved %}
        <h3>Most solved: <b>{{ most_solved[0].chal.name }}</b> with {{ most_solved[1] }}</b> solves</h3>
